function [init, out_out] = mfun_fvc_flux_observer(step, meas_in, u_s_ab_in, u_s_zoh_ab_in, w_M, p)
%MFUN_FVC_FLUX_OBSERVER Block FluxObserver of the control system.
%   FluxObserver of motulator. Generated by motulator_export from the MATLAB port of
%   motulator and called by the MATLAB Function block of the Simulink model, which adds
%   its folder to the MATLAB path. The parameters are the fields of the struct p (from
%   the mask, [] as NaN). The state is in persistent variables, of which each MATLAB
%   Function block has its own copy.
persistent self
if isempty(self)
    % Machine model: SaturatedSynchronousMachinePars with a GradNet flux map, or
    % SynchronousMachinePars with constant inductances
    par = machine_pars(p);
    k_o = p.k_o;
    if isnan(k_o(1))
        % Poles at zero speed at s = 0 and s = -2*sigma0
        L_s0 = incr_ind_mat(par, complex(0));
        k_o(1) = 0.25*par.R_s*(1/L_s0.L_dd + 1/L_s0.L_qq);
    end
    self = flux_observer_init(par, p.k_theta, k_o);
    % Flying start: the current at the start of the zero-voltage period
    self.i_s_ab_start = complex(0);
    self.catching = false;
end
meas = measurements_unpack(meas_in);
u_s_ab = complex_in(u_s_ab_in);
u_s_zoh_ab = complex_in(u_s_zoh_ab_in);
% Flying start: the current at the start of the zero-voltage period (step
% 2), and the estimates initialized from the current response at its end
% (the next step), see SpeedFluxObserver.catch
init = [0; w_M];
if step == 2
    self.i_s_ab_start = meas.i_c_ab;
    self.catching = true;
elseif self.catching
    self.catching = false; % Cancelled if the gates are blocked again
    [caught, w_M_init, theta_m, psi_s] = flux_observer_catch(self.par, ...
        meas.i_c_ab - self.i_s_ab_start, meas.i_c_ab, p.T_s, w_M);
    if caught && step == 0
        w_M = w_M_init;
        self.theta_m = theta_m;
        self.psi_s = psi_s;
        init = [1; w_M];
    end
end
if p.h == 0
    out = flux_observer_compute_output(self, u_s_zoh_ab, meas.i_c_ab, w_M, 0, 0);
else
    % Position error from the measured rotor angle (compute_feedback)
    n_p = self.par.n_p;
    eps = wrap(n_p*meas.theta_M - self.theta_m)/n_p;
    out = flux_observer_compute_output(self, u_s_zoh_ab, meas.i_c_ab, w_M, eps, p.h);
end
% Voltage for the control laws (DriveControlSystem.get_feedback), or the
% open-circuit voltage of the observer if unknown
if isnan(real(u_s_ab))
    out.u_s = out.u_s_zoh;
else
    out.u_s = exp(-1i*out.theta_c)*u_s_ab;
end
out_out = observer_outputs_pack(out);
self = flux_observer_update(self, p.T_s, out);
end

function par = machine_pars(p)
%MACHINE_PARS Machine model from the parameters par_* and gn_* of the block:
%   SaturatedSynchronousMachinePars with a GradNet flux map, or
%   SynchronousMachinePars with constant inductances.
if isnan(p.gn_in_dim)
    par = synchronous_machine_pars(p.par_n_p, p.par_R_s, p.par_L_d, p.par_L_q, ...
        p.par_psi_f, gradnet_placeholder());
else
    flux_map = gradnet(p.gn_in_dim, p.gn_mu_dim, p.gn_W, p.gn_b, p.gn_mu_log, ...
        p.gn_bias, p.gn_activation, p.gn_beta_log, p.gn_p, p.gn_in_base, ...
        p.gn_out_base);
    par = saturated_synchronous_machine_pars(p.par_n_p, p.par_R_s, flux_map);
end
end

function s = measurements_unpack(u)
%MEASUREMENTS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_c_ab', complex(u(1), u(2)), ...
    'u_dc', u(3), ...
    'theta_M', u(4));
end

function y = observer_outputs_pack(s)
%OBSERVER_OUTPUTS_PACK Signal vector of the struct s.
y = [ ...
    real(s.i_s);
    imag(s.i_s);
    real(s.u_s);
    imag(s.u_s);
    real(s.u_s_zoh);
    imag(s.u_s_zoh);
    real(s.psi_s);
    imag(s.psi_s);
    real(s.e_o);
    imag(s.e_o);
    s.eps;
    s.eps_f;
    real(s.psi_a);
    imag(s.psi_a);
    s.tau_M;
    s.w_c;
    s.w_m;
    s.w_M;
    s.theta_c;
    s.theta_m;
    s.psi_f;
    s.h];
end

function z = complex_in(u)
%COMPLEX_IN Complex number from a signal [real part; imaginary part].
z = complex(u(1), u(2));
end

function theta = wrap(theta)
%WRAP Limit the angle into the range [-pi, pi), as numpy.mod does.
x = rem(theta + pi, 2*pi);
if x < 0
    x = x + 2*pi;
end
theta = x - pi;
end

function [Phi, Gamma] = hold_equivalent(T_s, w_c)
%HOLD_EQUIVALENT Hold-equivalent discretization of a vector integrator in rotating
%   coordinates (hold_equivalent): the coefficients discretize d(psi)/dt = u + v -
%   1j*w_c*psi, where psi is in coordinates rotating at w_c, u is constant in
%   stator coordinates, and v is constant in the rotating coordinates over the
%   sampling period. Then, psi(k+1) = Phi*(psi(k) + T_s*u(k)) + Gamma*v(k), with
%   Phi = exp(-1j*w_c*T_s) and Gamma = (1 - Phi)/(1j*w_c).
% Half-angle form, requiring a single sine-cosine pair. The sinc function is
% computed as numpy.sinc(x/pi).
x = 0.5*w_c*T_s;
exp_jx = exp(-1i*x);
if x ~= 0
    y = pi*(x/pi);
else
    y = pi*1e-20;
end
Phi = exp_jx*exp_jx;
Gamma = T_s*(sin(y)/y)*exp_jx;
end

function net = gradnet(in_dim, mu_dim, W, b, mu_log, bias, activation, beta_log, ...
    p, in_base, out_base)
%GRADNET GradNet from its parameters (the fields of the GradNet structs of the
%   model initialization), W being an embed_dim-by-in_dim matrix. The field mu has
%   the gains of the linear term, zero for the inputs beyond the first mu_dim.
mu = zeros(size(W, 2), 1);
n_mu = min(mu_dim, numel(mu_log));
mu(1:n_mu) = exp(mu_log(1:n_mu));
net = struct('in_dim', in_dim, 'mu_dim', mu_dim, 'embed_dim', size(W, 1), ...
    'W', W, 'b', b(:), 'mu', mu, 'bias', bias(:), 'activation', activation, ...
    'beta', exp(beta_log), 'p', p, 'in_base', in_base, 'out_base', out_base);
end

function net = gradnet_placeholder()
%GRADNET_PLACEHOLDER GradNet with in_dim = 2 for the machine models without a flux
%   map, so that the code using a flux map compiles.
net = gradnet(2, 0, zeros(1, 2), 0, zeros(2, 1), zeros(2, 1), 2, 0, 1, 1, 1);
end

function [z, jac] = gradnet_forward(net, x, want_jac)
%GRADNET_FORWARD Output of the network for a per-unit input x (a column vector),
%   as GradNetFunction.__call__. If want_jac is true, the Jacobian matrix is
%   computed too. The Jacobians of both activations are of the form
%   c*(diag(d) - u*u^T), so the Jacobian of the network is
%   diag(mu) + c*(W^T diag(d) W - v*v^T) with v = W^T u.
W = net.W;
beta = net.beta;
% Module: W^T act(W x + b)
h = beta*(W*x + net.b);
if net.activation == 1
    % PNormGradient: x^q/(1 + sum(x^(q + 1)))^(q/(q + 1)) with q = p - 1
    q = net.p - 1;
    norm_ = 1 + sum(h.^(q + 1));
    norm_r = norm_^(q/(q + 1));
    c = beta*q/norm_r;
    d = h.^(q - 1);
    u = h.^q/sqrt(norm_);
    h = h.^q/norm_r;
else
    % Softmax
    h = exp(h - max(h));
    h = h/sum(h);
    c = beta;
    d = h;
    u = h;
end
% Linear term (for the first mu_dim inputs), bias, and the module
z = net.mu.*x + net.bias + W'*h;
jac = zeros(size(W, 2));
if want_jac
    v = W'*u;
    jac = diag(net.mu) + c*(W'*(d.*W) - v*v');
end
end

function y = gradnet_map(net, x)
%GRADNET_MAP Evaluate the map (FluxMap or CurrentMap in motulator), symmetrized
%   about the d-axis. The input and output are in SI units.
% Evaluate at the input and its conjugate, and symmetrize about the d-axis
x1 = [real(x); imag(x)]/net.in_base;
x2 = [x1(1); -x1(2)];
z1 = gradnet_forward(net, x1, false);
z2 = gradnet_forward(net, x2, false);
y = 0.5*((z1(1) + 1i*z1(2)) + conj(z2(1) + 1i*z2(2)));
y = y*net.out_base;
end

function jac = gradnet_map_jacobian(net, x)
%GRADNET_MAP_JACOBIAN Jacobian matrix [dy_d/dx_d, dy_d/dx_q; dy_q/dx_d, dy_q/dx_q]
%   of the map (CurrentMap.jacobian in motulator) in SI units.
% Symmetrize as in gradnet_map: the conjugation flips the signs of the off-diagonal
% elements
x1 = [real(x); imag(x)]/net.in_base;
x2 = [x1(1); -x1(2)];
[~, jac1] = gradnet_forward(net, x1, true);
[~, jac2] = gradnet_forward(net, x2, true);
jac = 0.5*(net.out_base/net.in_base)*(jac1 + [1, -1; -1, 1].*jac2);
end

function par = synchronous_machine_pars(n_p, R_s, L_d, L_q, psi_f, flux_map)
%SYNCHRONOUS_MACHINE_PARS Constant inductances (SynchronousMachinePars), with an
%   unused flux map.
par = struct('n_p', n_p, 'R_s', R_s, 'L_d', L_d, 'L_q', L_q, 'psi_f', psi_f, ...
    'saturated', false, 'flux_map', flux_map, 'L_d0', 0, 'L_q0', 0);
end

function par = saturated_synchronous_machine_pars(n_p, R_s, flux_map)
%SATURATED_SYNCHRONOUS_MACHINE_PARS GradNet flux map
%   (SaturatedSynchronousMachinePars).
par = struct('n_p', n_p, 'R_s', R_s, 'L_d', 0, 'L_q', 0, 'psi_f', 0, ...
    'saturated', true, 'flux_map', flux_map, 'L_d0', 0, 'L_q0', 0);
% As in SaturatedSynchronousMachinePars.__post_init__
par.psi_f = real(psi_s_dq(par, complex(0)));
L0 = incr_ind_mat(par, complex(0));
par.L_d0 = L0.L_dd;
par.L_q0 = L0.L_qq;
if par.psi_f < 1e-3 % EPS of motulator/drive/utils/_parameters.py
    par.psi_f = 0; % No permanent magnets
end
end

function psi_s = psi_s_dq(par, i_s)
%PSI_S_DQ Stator flux linkage as a function of the stator current.
if par.saturated
    psi_s = gradnet_map(par.flux_map, i_s);
else
    psi_s = par.L_d*real(i_s) + par.psi_f + 1i*par.L_q*imag(i_s);
end
end

function L = incr_ind_mat(par, i_s)
%INCR_IND_MAT Incremental inductance matrix [L_dd, L_dq; L_dq, L_qq] as a struct.
if ~par.saturated
    L = struct('L_dd', par.L_d, 'L_dq', 0, 'L_qq', par.L_q);
    return
end
jac = gradnet_map_jacobian(par.flux_map, i_s);
L = struct('L_dd', jac(1, 1), 'L_dq', jac(1, 2), 'L_qq', jac(2, 2));
end

function psi_a = aux_flux(L, i_s, psi_s)
%AUX_FLUX Auxiliary flux linkage.
psi_a = psi_s - L.L_qq*real(i_s) - 1i*L.L_dd*imag(i_s) + 1i*L.L_dq*conj(i_s);
end

function self = flux_observer_init(par, k_theta, k_o)
%FLUX_OBSERVER_INIT Flux observer in estimated rotor coordinates (FluxObserver),
%   with the observer gain k_o(w_m) = k_o(1) + k_o(2)*abs(w_m).
self = struct('par', par, 'k_theta', k_theta, 'k_o', [k_o(1), k_o(2)], ...
    'theta_m', 0, 'psi_s', complex(par.psi_f), 'T_s_prev', 0);
end

function out = flux_observer_compute_output(self, u_s_ab, i_s_ab, w_M, eps_ext, h)
%FLUX_OBSERVER_COMPUTE_OUTPUT Feedback signals (ObserverOutputs) without u_dc and
%   tau_L. The weight h of the external position error signal eps_ext selects
%   between the sensorless (h = 0) and sensored (h = 1) modes. The voltage u_s_ab is
%   NaN if unknown (blocked gates).
par = self.par;
% Coordinate system angle equals the estimated rotor angle
theta_c = self.theta_m;
% Current vector in (estimated) rotor coordinates. The voltage averaged over the
% previous and ongoing sampling periods is set by the control system
% (DriveControlSystem.get_feedback).
i_s = exp(-1i*theta_c)*i_s_ab;
% Flux estimation error
psi_s_model = psi_s_dq(par, i_s);
e_o = psi_s_model - self.psi_s;
% Auxiliary flux
L = incr_ind_mat(par, i_s);
psi_a = aux_flux(L, i_s, psi_s_model);
% Error signals for the rotor angle and PM-flux estimation
if psi_a ~= 0
    ratio = e_o/psi_a;
else
    ratio = complex(0);
end
eps = h*eps_ext - (1 - h)*imag(ratio)/par.n_p;
eps_f = -(1 - h)*real(ratio);
% Rotor speed and the angular speed of the coordinate system
w_m = par.n_p*w_M;
w_c = w_m + self.k_theta*par.n_p*eps;
% Voltage vector in the observer coordinates, or the open-circuit voltage of the
% model if the voltage is unknown (NaN, blocked gates): the back-EMF of the flux
% estimate at the rotor speed, averaged over the sampling period (that of the
% previous period), and the resistive voltage drop
if ~isnan(real(u_s_ab))
    u_s_zoh = exp(-1i*theta_c)*u_s_ab;
elseif self.T_s_prev > 0
    emf = (exp(1i*w_m*self.T_s_prev) - 1)/self.T_s_prev*self.psi_s;
    u_s_zoh = emf + par.R_s*i_s;
else
    u_s_zoh = 1i*w_m*self.psi_s + par.R_s*i_s;
end
% Torque estimate
tau_M = 1.5*par.n_p*imag(i_s*conj(self.psi_s));
out = struct('i_s', i_s, 'u_s', complex(0), 'u_s_zoh', u_s_zoh, ...
    'psi_s', self.psi_s, 'e_o', e_o, 'eps', eps, 'eps_f', eps_f, 'psi_a', psi_a, ...
    'tau_M', tau_M, 'w_c', w_c, 'w_m', w_m, 'w_M', w_M, 'theta_c', theta_c, ...
    'theta_m', self.theta_m, 'psi_f', par.psi_f, 'h', h);
end

function self = flux_observer_update(self, T_s, out)
%FLUX_OBSERVER_UPDATE Update the flux and rotor angle estimates.
par = self.par;
k_o1 = self.k_o(1) + self.k_o(2)*abs(out.w_m);
if out.psi_a ~= 0
    k_o2 = (1 - out.h)*(k_o1*out.psi_a/conj(out.psi_a));
else
    k_o2 = complex((1 - out.h)*k_o1);
end
% Correct the flux estimate at the sampling instant and predict it to the next
% sampling instant. The stator voltage is constant in stator coordinates, while the
% resistive voltage drop is constant in the observer coordinates. The PM-flux
% estimation gain k_f is zero.
v_err = k_o1*out.e_o + k_o2*conj(out.e_o);
psi_s = out.psi_s + T_s*v_err;
[Phi, Gamma] = hold_equivalent(T_s, out.w_c);
self.psi_s = Phi*(psi_s + T_s*out.u_s_zoh) - Gamma*par.R_s*out.i_s;
self.theta_m = wrap(self.theta_m + T_s*out.w_c);
self.T_s_prev = T_s;
end

function [caught, w_M, theta_m, psi_s] = flux_observer_catch(par, delta_i_s_ab, ...
    i_s_ab, T_s, w_M)
%FLUX_OBSERVER_CATCH Estimates initialized from the current response delta_i_s_ab to
%   a zero-voltage period of length T_s, i_s_ab being the current at its end
%   (SpeedFluxObserver.catch): the back-EMF drives the current along the negative q
%   axis of the rotor, which gives the rotor angle and the speed magnitude, the
%   direction of rotation being taken from the speed estimate w_M, which is updated
%   with the angle and flux estimates. If the back-EMF estimate does not exceed the
%   resistive voltage drop of the current (standstill, or a current that has not
%   decayed) or the machine has no magnets, caught is false and the estimates are
%   not valid.
L = incr_ind_mat(par, complex(0));
e_s_ab = -L.L_qq*delta_i_s_ab/T_s; % Back-EMF
% The resistive decay of a residual current (the d-axis current through L_d) must
% not be taken for the back-EMF
i_max = max(abs(i_s_ab), abs(i_s_ab - delta_i_s_ab));
caught = abs(e_s_ab) > par.R_s*i_max*max(L.L_qq/L.L_dd, 1) && par.psi_f ~= 0;
theta_m = 0;
psi_s = complex(0);
if ~caught
    return
end
if w_M >= 0
    sign_w = 1;
else
    sign_w = -1;
end
w_m = sign_w*abs(e_s_ab)/par.psi_f;
% The response lags the rotor angle at the end of the period, since the back-EMF
% rotates during the period
theta_m = wrap(angle(e_s_ab) - sign_w*pi/2 + w_m*T_s*L.L_qq/(2*L.L_dd));
w_M = w_m/par.n_p;
psi_s = complex(psi_s_dq(par, exp(-1i*theta_m)*i_s_ab));
end
